class Lot extends DataClass implements Insertable<Lot> {
  final String id;
  final DateTime updatedAt;
  final bool deleted;
  final String quantityMode;
  final double? freshBags;
  final double? driedBags;
  final String code;
  final Crop crop;
  final int seasonStartYear;
  final String title;
  final List<String> plotIds;
  final DateTime harvestedOn;
  final int? palmsClimbed;
  final double? freshKg;
  final DateTime? dryingStartedOn;
  final DateTime? dryingEndedOn;
  final int dryingTargetDays;
  final String yard;

  /// Dried nuts in husk, weighed before peeling.
  final double? driedKg;
  final DateTime? peeledOn;

  /// Chali after peeling.
  final double? chaliKg;
  final DateTime? storedOn;
  final DateTime? takenOutOn;
  final String storagePlace;
  final int? bags;

  /// Paise per kg on the day it was stored.
  final int? storedPricePerKg;
  final String notes;
  const Lot({
    required this.id,
    required this.updatedAt,
    required this.deleted,
    required this.quantityMode,
    this.freshBags,
    this.driedBags,
    required this.code,
    required this.crop,
    required this.seasonStartYear,
    required this.title,
    required this.plotIds,
    required this.harvestedOn,
    this.palmsClimbed,
    this.freshKg,
    this.dryingStartedOn,
    this.dryingEndedOn,
    required this.dryingTargetDays,
    required this.yard,
    this.driedKg,
    this.peeledOn,
    this.chaliKg,
    this.storedOn,
    this.takenOutOn,
    required this.storagePlace,
    this.bags,
    this.storedPricePerKg,
    required this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted'] = Variable<bool>(deleted);
    map['quantity_mode'] = Variable<String>(quantityMode);
    if (!nullToAbsent || freshBags != null) {
      map['fresh_bags'] = Variable<double>(freshBags);
    }
    if (!nullToAbsent || driedBags != null) {
      map['dried_bags'] = Variable<double>(driedBags);
    }
    map['code'] = Variable<String>(code);
    {
      map['crop'] = Variable<String>($LotsTable.$convertercrop.toSql(crop));
    }
    map['season_start_year'] = Variable<int>(seasonStartYear);
    map['title'] = Variable<String>(title);
    {
      map['plot_ids'] = Variable<String>(
        $LotsTable.$converterplotIds.toSql(plotIds),
      );
    }
    map['harvested_on'] = Variable<DateTime>(harvestedOn);
    if (!nullToAbsent || palmsClimbed != null) {
      map['palms_climbed'] = Variable<int>(palmsClimbed);
    }
    if (!nullToAbsent || freshKg != null) {
      map['fresh_kg'] = Variable<double>(freshKg);
    }
    if (!nullToAbsent || dryingStartedOn != null) {
      map['drying_started_on'] = Variable<DateTime>(dryingStartedOn);
    }
    if (!nullToAbsent || dryingEndedOn != null) {
      map['drying_ended_on'] = Variable<DateTime>(dryingEndedOn);
    }
    map['drying_target_days'] = Variable<int>(dryingTargetDays);
    map['yard'] = Variable<String>(yard);
    if (!nullToAbsent || driedKg != null) {
      map['dried_kg'] = Variable<double>(driedKg);
    }
    if (!nullToAbsent || peeledOn != null) {
      map['peeled_on'] = Variable<DateTime>(peeledOn);
    }
    if (!nullToAbsent || chaliKg != null) {
      map['chali_kg'] = Variable<double>(chaliKg);
    }
    if (!nullToAbsent || storedOn != null) {
      map['stored_on'] = Variable<DateTime>(storedOn);
    }
    if (!nullToAbsent || takenOutOn != null) {
      map['taken_out_on'] = Variable<DateTime>(takenOutOn);
    }
    map['storage_place'] = Variable<String>(storagePlace);
    if (!nullToAbsent || bags != null) {
      map['bags'] = Variable<int>(bags);
    }
    if (!nullToAbsent || storedPricePerKg != null) {
      map['stored_price_per_kg'] = Variable<int>(storedPricePerKg);
    }
    map['notes'] = Variable<String>(notes);
    return map;
  }

  LotsCompanion toCompanion(bool nullToAbsent) {
    return LotsCompanion(
      id: Value(id),
      updatedAt: Value(updatedAt),
      deleted: Value(deleted),
      quantityMode: Value(quantityMode),
      freshBags: freshBags == null && nullToAbsent
          ? const Value.absent()
          : Value(freshBags),
      driedBags: driedBags == null && nullToAbsent
          ? const Value.absent()
          : Value(driedBags),
      code: Value(code),
      crop: Value(crop),
      seasonStartYear: Value(seasonStartYear),
      title: Value(title),
      plotIds: Value(plotIds),
      harvestedOn: Value(harvestedOn),
      palmsClimbed: palmsClimbed == null && nullToAbsent
          ? const Value.absent()
          : Value(palmsClimbed),
      freshKg: freshKg == null && nullToAbsent
          ? const Value.absent()
          : Value(freshKg),
      dryingStartedOn: dryingStartedOn == null && nullToAbsent
          ? const Value.absent()
          : Value(dryingStartedOn),
      dryingEndedOn: dryingEndedOn == null && nullToAbsent
          ? const Value.absent()
          : Value(dryingEndedOn),
      dryingTargetDays: Value(dryingTargetDays),
      yard: Value(yard),
      driedKg: driedKg == null && nullToAbsent
          ? const Value.absent()
          : Value(driedKg),
      peeledOn: peeledOn == null && nullToAbsent
          ? const Value.absent()
          : Value(peeledOn),
      chaliKg: chaliKg == null && nullToAbsent
          ? const Value.absent()
          : Value(chaliKg),
      storedOn: storedOn == null && nullToAbsent
          ? const Value.absent()
          : Value(storedOn),
      takenOutOn: takenOutOn == null && nullToAbsent
          ? const Value.absent()
          : Value(takenOutOn),
      storagePlace: Value(storagePlace),
      bags: bags == null && nullToAbsent ? const Value.absent() : Value(bags),
      storedPricePerKg: storedPricePerKg == null && nullToAbsent
          ? const Value.absent()
          : Value(storedPricePerKg),
      notes: Value(notes),
    );
  }

  factory Lot.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Lot(
      id: serializer.fromJson<String>(json['id']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deleted: serializer.fromJson<bool>(json['deleted']),
      quantityMode: serializer.fromJson<String>(json['quantityMode']),
      freshBags: serializer.fromJson<double?>(json['freshBags']),
      driedBags: serializer.fromJson<double?>(json['driedBags']),
      code: serializer.fromJson<String>(json['code']),
      crop: $LotsTable.$convertercrop.fromJson(
        serializer.fromJson<String>(json['crop']),
      ),
      seasonStartYear: serializer.fromJson<int>(json['seasonStartYear']),
      title: serializer.fromJson<String>(json['title']),
      plotIds: serializer.fromJson<List<String>>(json['plotIds']),
      harvestedOn: serializer.fromJson<DateTime>(json['harvestedOn']),
      palmsClimbed: serializer.fromJson<int?>(json['palmsClimbed']),
      freshKg: serializer.fromJson<double?>(json['freshKg']),
      dryingStartedOn: serializer.fromJson<DateTime?>(json['dryingStartedOn']),
      dryingEndedOn: serializer.fromJson<DateTime?>(json['dryingEndedOn']),
      dryingTargetDays: serializer.fromJson<int>(json['dryingTargetDays']),
      yard: serializer.fromJson<String>(json['yard']),
      driedKg: serializer.fromJson<double?>(json['driedKg']),
      peeledOn: serializer.fromJson<DateTime?>(json['peeledOn']),
      chaliKg: serializer.fromJson<double?>(json['chaliKg']),
      storedOn: serializer.fromJson<DateTime?>(json['storedOn']),
      takenOutOn: serializer.fromJson<DateTime?>(json['takenOutOn']),
      storagePlace: serializer.fromJson<String>(json['storagePlace']),
      bags: serializer.fromJson<int?>(json['bags']),
      storedPricePerKg: serializer.fromJson<int?>(json['storedPricePerKg']),
      notes: serializer.fromJson<String>(json['notes']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deleted': serializer.toJson<bool>(deleted),
      'quantityMode': serializer.toJson<String>(quantityMode),
