      'dryingEndedOn': serializer.toJson<DateTime?>(dryingEndedOn),
      'dryingTargetDays': serializer.toJson<int>(dryingTargetDays),
      'yard': serializer.toJson<String>(yard),
      'driedKg': serializer.toJson<double?>(driedKg),
