class Sale extends DataClass implements Insertable<Sale> {
  final String id;
  final DateTime updatedAt;
  final bool deleted;
  final DateTime date;
  final String buyerId;
  final String? lotId;

  /// Moisture cut, commission, hamali, transport — paise, taken off the gross.
  final int deductions;
  final String deductionNote;
  final int received;
  final String notes;
  const Sale({
    required this.id,
    required this.updatedAt,
    required this.deleted,
    required this.date,
    required this.buyerId,
    this.lotId,
    required this.deductions,
    required this.deductionNote,
    required this.received,
    required this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted'] = Variable<bool>(deleted);
    map['date'] = Variable<DateTime>(date);
    map['buyer_id'] = Variable<String>(buyerId);
    if (!nullToAbsent || lotId != null) {
      map['lot_id'] = Variable<String>(lotId);
    }
    map['deductions'] = Variable<int>(deductions);
    map['deduction_note'] = Variable<String>(deductionNote);
    map['received'] = Variable<int>(received);
    map['notes'] = Variable<String>(notes);
    return map;
  }

  SalesCompanion toCompanion(bool nullToAbsent) {
    return SalesCompanion(
      id: Value(id),
      updatedAt: Value(updatedAt),
      deleted: Value(deleted),
      date: Value(date),
      buyerId: Value(buyerId),
      lotId: lotId == null && nullToAbsent
          ? const Value.absent()
          : Value(lotId),
      deductions: Value(deductions),
      deductionNote: Value(deductionNote),
      received: Value(received),
      notes: Value(notes),
    );
  }

  factory Sale.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Sale(
      id: serializer.fromJson<String>(json['id']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deleted: serializer.fromJson<bool>(json['deleted']),
      date: serializer.fromJson<DateTime>(json['date']),
      buyerId: serializer.fromJson<String>(json['buyerId']),
      lotId: serializer.fromJson<String?>(json['lotId']),
      deductions: serializer.fromJson<int>(json['deductions']),
      deductionNote: serializer.fromJson<String>(json['deductionNote']),
      received: serializer.fromJson<int>(json['received']),
      notes: serializer.fromJson<String>(json['notes']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deleted': serializer.toJson<bool>(deleted),
      'date': serializer.toJson<DateTime>(date),
      'buyerId': serializer.toJson<String>(buyerId),
      'lotId': serializer.toJson<String?>(lotId),
      'deductions': serializer.toJson<int>(deductions),
      'deductionNote': serializer.toJson<String>(deductionNote),
      'received': serializer.toJson<int>(received),
      'notes': serializer.toJson<String>(notes),
    };
  }

  Sale copyWith({
    String? id,
    DateTime? updatedAt,
    bool? deleted,
    DateTime? date,
    String? buyerId,
    Value<String?> lotId = const Value.absent(),
    int? deductions,
    String? deductionNote,
    int? received,
    String? notes,
  }) => Sale(
    id: id ?? this.id,
    updatedAt: updatedAt ?? this.updatedAt,
    deleted: deleted ?? this.deleted,
    date: date ?? this.date,
    buyerId: buyerId ?? this.buyerId,
    lotId: lotId.present ? lotId.value : this.lotId,
    deductions: deductions ?? this.deductions,
    deductionNote: deductionNote ?? this.deductionNote,
    received: received ?? this.received,
    notes: notes ?? this.notes,
  );
  Sale copyWithCompanion(SalesCompanion data) {
    return Sale(
      id: data.id.present ? data.id.value : this.id,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      deleted: data.deleted.present ? data.deleted.value : this.deleted,
      date: data.date.present ? data.date.value : this.date,
      buyerId: data.buyerId.present ? data.buyerId.value : this.buyerId,
      lotId: data.lotId.present ? data.lotId.value : this.lotId,
      deductions: data.deductions.present
          ? data.deductions.value
          : this.deductions,
      deductionNote: data.deductionNote.present
          ? data.deductionNote.value
          : this.deductionNote,
      received: data.received.present ? data.received.value : this.received,
