      map['plot_ids'] = Variable<String>(
        $LandParcelsTable.$converterplotIds.toSql(plotIds.value),
      );
    }
    if (notes.present) {
      map['notes'] = Variable<String>(notes.value);
    }
    if (rowid.present) {
      map['rowid'] = Variable<int>(rowid.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('LandParcelsCompanion(')
          ..write('id: $id, ')
          ..write('updatedAt: $updatedAt, ')
          ..write('deleted: $deleted, ')
          ..write('surveyNumber: $surveyNumber, ')
          ..write('hissa: $hissa, ')
          ..write('village: $village, ')
          ..write('acres: $acres, ')
          ..write('plotIds: $plotIds, ')
          ..write('notes: $notes, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

