class Loan extends DataClass implements Insertable<Loan> {
  final String id;
  final DateTime updatedAt;
  final bool deleted;
  final String lender;
  final String lenderKind;
  final String kind;
  final int sanctioned;
  final DateTime sanctionedOn;
  final double annualRate;
  final String interestMethod;
  final int compoundingMonths;
  final int tenureMonths;
  final String? parcelId;
  final String status;
  final bool timelyConcession;
  final String notes;
  const Loan({
    required this.id,
    required this.updatedAt,
    required this.deleted,
    required this.lender,
    required this.lenderKind,
    required this.kind,
    required this.sanctioned,
    required this.sanctionedOn,
    required this.annualRate,
    required this.interestMethod,
    required this.compoundingMonths,
    required this.tenureMonths,
    this.parcelId,
    required this.status,
    required this.timelyConcession,
    required this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    map['deleted'] = Variable<bool>(deleted);
    map['lender'] = Variable<String>(lender);
    map['lender_kind'] = Variable<String>(lenderKind);
    map['kind'] = Variable<String>(kind);
    map['sanctioned'] = Variable<int>(sanctioned);
    map['sanctioned_on'] = Variable<DateTime>(sanctionedOn);
    map['annual_rate'] = Variable<double>(annualRate);
    map['interest_method'] = Variable<String>(interestMethod);
    map['compounding_months'] = Variable<int>(compoundingMonths);
    map['tenure_months'] = Variable<int>(tenureMonths);
    if (!nullToAbsent || parcelId != null) {
      map['parcel_id'] = Variable<String>(parcelId);
    }
    map['status'] = Variable<String>(status);
    map['timely_concession'] = Variable<bool>(timelyConcession);
    map['notes'] = Variable<String>(notes);
    return map;
  }

  LoansCompanion toCompanion(bool nullToAbsent) {
    return LoansCompanion(
      id: Value(id),
      updatedAt: Value(updatedAt),
      deleted: Value(deleted),
      lender: Value(lender),
      lenderKind: Value(lenderKind),
      kind: Value(kind),
      sanctioned: Value(sanctioned),
      sanctionedOn: Value(sanctionedOn),
      annualRate: Value(annualRate),
      interestMethod: Value(interestMethod),
      compoundingMonths: Value(compoundingMonths),
      tenureMonths: Value(tenureMonths),
      parcelId: parcelId == null && nullToAbsent
          ? const Value.absent()
          : Value(parcelId),
      status: Value(status),
      timelyConcession: Value(timelyConcession),
      notes: Value(notes),
    );
  }

